// src/lib/metricEngine/rules/outputVolume.ts
function blendOutputGrowthSignal(previousSignal, physicalSignal, historySpanTurns) {
  if (physicalSignal === null || !Number.isFinite(physicalSignal)) return previousSignal;
  const weight = Number.isFinite(historySpanTurns) ? Math.max(
    0,
    Math.min(
      1,
      (historySpanTurns - REVENUE_TREND_MIN_SPAN) / (REVENUE_TREND_TARGET_SPAN - REVENUE_TREND_MIN_SPAN)
    )
  ) : 0;
  return previousSignal * (1 - weight) + physicalSignal * weight;
}

