// src/lib/metricEngine/spendingChannel.ts
function fundingResponse(perCapita, halfSaturation = 1, max = 100) {
  if (!(perCapita > 0)) return 0;
  return max * perCapita / (perCapita + halfSaturation);
}
function maintenanceDecay(prev, target, decay) {
  return Math.max(prev - decay, target);
}

