// src/lib/metricEngine/outputGap.ts
var GAP_CLOSURE = 1.5;
var OUTPUT_GAP_BOUND = [-15, 15];
var GDP_GROWTH_BOUND = [-15, 15];
function advanceOutputGap(prevGap, sectorSignal, potential, turnsPerYear) {
  const g0Raw = Number.isFinite(prevGap) ? prevGap : 0;
  const g0 = Math.max(OUTPUT_GAP_BOUND[0], Math.min(OUTPUT_GAP_BOUND[1], g0Raw));
  const sector = Number.isFinite(sectorSignal) ? sectorSignal : 0;
  const potRaw = Number.isFinite(potential) ? potential : 0;
  const pot = Math.max(GDP_GROWTH_BOUND[0], Math.min(GDP_GROWTH_BOUND[1], potRaw));
  const impulse = sector - pot;
  const tpy = Number.isFinite(turnsPerYear) && turnsPerYear > 0 ? turnsPerYear : 1;
  const rawGap = g0 + (impulse - GAP_CLOSURE * g0) / tpy;
  const feasibleGap = [
    Math.max(OUTPUT_GAP_BOUND[0], g0 + (GDP_GROWTH_BOUND[0] - pot) / tpy),
    Math.min(OUTPUT_GAP_BOUND[1], g0 + (GDP_GROWTH_BOUND[1] - pot) / tpy)
  ];
  const gap = Math.max(feasibleGap[0], Math.min(feasibleGap[1], rawGap));
  const gdpGrowth = pot + (gap - g0) * tpy;
  return { gap, gdpGrowth, impulse };
}

// src/lib/metricEngine/potentialGrowth.ts
var TFP_BASELINE = 1.2;
var TFP_REFERENCE_INPUTS = {
  rdIntensity: 2.5,
  workforceSkill: 60,
  transportEfficiency: 55,
  broadbandAccess: 75,
  powerGridReliability: 98.5,
  urbanizationRate: 55
};
var TFP_BOUNDS = [0.2, 2.6];
function agglomeration(urbanizationRate) {
  const u = Math.max(0, Math.min(100, urbanizationRate));
  return u / (u + 40);
}
var orRef = (v, ref) => typeof v === "number" && Number.isFinite(v) ? v : ref;
function tfpBasket(inputs) {
  const ref = TFP_REFERENCE_INPUTS;
  const rd = orRef(inputs.rdIntensity, ref.rdIntensity);
  const skill = orRef(inputs.workforceSkill, ref.workforceSkill);
  const transport = orRef(inputs.transportEfficiency, ref.transportEfficiency);
  const broadband = orRef(inputs.broadbandAccess, ref.broadbandAccess);
  const grid = orRef(inputs.powerGridReliability, ref.powerGridReliability);
  const urban = orRef(inputs.urbanizationRate, ref.urbanizationRate);
  const infraTerm = 0.2 * ((transport - ref.transportEfficiency) / 45) + 0.15 * ((broadband - ref.broadbandAccess) / 25) + 0.1 * ((grid - ref.powerGridReliability) / 1.45);
  const tfp = TFP_BASELINE + 0.25 * ((rd - ref.rdIntensity) / 2) + 0.5 * ((skill - ref.workforceSkill) / 30) + infraTerm + 1.5 * (agglomeration(urban) - agglomeration(ref.urbanizationRate));
  return Math.max(TFP_BOUNDS[0], Math.min(TFP_BOUNDS[1], tfp));
}

