// src/lib/military/warDamage.ts
var WAR_ROAD_TARGET_PENALTY = 25;
var WAR_ROAD_EXTRA_DECAY = 0.2;
function warRoadTargetPenalty(damage) {
  const p = damage?.frontProgress ?? 0;
  if (!Number.isFinite(p) || p <= 0) return 0;
  return WAR_ROAD_TARGET_PENALTY * Math.min(1, p);
}
function warRoadExtraDecay(damage) {
  const p = damage?.frontProgress ?? 0;
  if (!Number.isFinite(p) || p <= 0) return 0;
  return WAR_ROAD_EXTRA_DECAY * Math.min(1, p);
}

// src/lib/metricEngine/registry/infrastructure.ts
var INFRA_SPEND_HALF_SAT = 1200;
var spendResp3 = (ctx) => fundingResponse(ctx.spending["infrastructure"] ?? 0, INFRA_SPEND_HALF_SAT, 100);
var supportedLevel = (ctx, floor, span) => floor + spendResp3(ctx) / 100 * span;
var capitalCompute = (id, floor, span, decayPerTurn, inertia, fallback) => (ctx) => {
  const base = Number.isFinite(ctx.prevSimBaseline[id]) ? ctx.prevSimBaseline[id] : Number.isFinite(ctx.prev[id]) ? ctx.prev[id] : fallback;
  const effectiveDecay = decayPerTurn / (1 - inertia);
  return maintenanceDecay(base, supportedLevel(ctx, floor, span), effectiveDecay);
};
var ROAD_FREIGHT_REFERENCE_SHARE = 0.05;
var ROAD_FREIGHT_MAX_BONUS = 6;
var ROAD_FREIGHT_MAX_PENALTY = 4;
function freightLogisticsAdequacyTerm(rows) {
  let logistics = 0;
  let total = 0;
  for (const row of rows) {
    const rev = Number.isFinite(row.revenue) ? Math.max(0, row.revenue) : 0;
    if (rev <= 0) continue;
    total += rev;
    if (row.sectorType === "logistics") logistics += rev;
  }
  if (total <= 0) return 0;
  const share = logistics / total;
  const ratio = share / ROAD_FREIGHT_REFERENCE_SHARE;
  if (ratio >= 1) {
    return ROAD_FREIGHT_MAX_BONUS * Math.min(1, (ratio - 1) / 1.5);
  }
  return -ROAD_FREIGHT_MAX_PENALTY * (1 - ratio);
}
var roadConditionNode = {
  id: "infrastructure.roadCondition",
  categoryId: "infrastructure",
  metricId: "roadCondition",
  kind: "derived",
  // Maintenance-decay off infrastructure spend, plus the region's own freight
  // provisioning (ticket #1143) so logistics-sector build-out lifts the metric
  // the corp margin penalty reads.
  inputs: [
    { spending: "infrastructure" },
    { provider: "sectorRevenueTax" },
    // A war fought across this country's ground. See `warDamage`: the host is
    // damaged, an expeditionary belligerent is not.
    { provider: "warDamage" }
  ],
  bounds: [0, 100],
  inertia: 0.85,
  decimals: 2,
  // 2dp storage: per-turn decay steps (~0.05) stall on a 0.1 rounding grain
  // THRESHOLDS [40 worst, 90 best]; ~3 pts/yr erosion without upkeep. Same
  // baseline-decay semantics as capitalCompute (decay the simBaseline, scaled by
  // 1/(1−inertia)) with the freight-adequacy term added to the supported target.
  compute: (ctx) => {
    const id = "infrastructure.roadCondition";
    const base = Number.isFinite(ctx.prevSimBaseline[id]) ? ctx.prevSimBaseline[id] : Number.isFinite(ctx.prev[id]) ? ctx.prev[id] : 65;
    const payload = ctx.providers["sectorRevenueTax"];
    const freightTerm = payload ? freightLogisticsAdequacyTerm([...payload.owned, ...payload.unowned]) : 0;
    const war = ctx.providers["warDamage"];
    const target = supportedLevel(ctx, 35, 60) + freightTerm - warRoadTargetPenalty(war);
    const decay = (0.06 + warRoadExtraDecay(war)) / (1 - 0.85);
    return maintenanceDecay(base, target, decay);
  }
};
