function getMetricDefinition(categoryId, metricId) {
  const category = metricCategories.find((c) => c.id === categoryId);
  return category?.metrics.find((m) => m.id === metricId);
}
var METRIC_DEFS_BY_CATEGORY = metricCategories.reduce(
  (acc, cat) => {
    const catMap = {};
    for (const metric of cat.metrics) catMap[metric.id] = metric;
    acc[cat.id] = catMap;
    return acc;
  },
  {}
);
function buildFlatMap(select) {
  const out = {};
  for (const cat of metricCategories) {
    for (const metric of cat.metrics) {
      const value = select(metric);
      if (value !== void 0) out[metric.id] = value;
    }
  }
  return out;
}
var METRIC_NAMES = buildFlatMap((d) => d.shortName ?? d.name);
var METRIC_DESCRIPTIONS = buildFlatMap(
  (d) => d.detailedDescription ?? d.description
);

