var BASE_RATES_USD = {
  US: 1,
  UK: 0.75,
  JP: 106,
  DE: 0.92,
  CN: 7.2,
  BR: 5,
  IE: 0.92,
  NG: 1
};
function toUsd(localValue, countryId) {
  const rate = BASE_RATES_USD[countryId];
  if (!rate || rate === 1) return localValue;
  return localValue / rate;
}

