// src/lib/politicalMetrics/aggregate.ts
function categoryScore(values, categoryId) {
  const fams = FAMILIES_BY_CATEGORY[categoryId];
  return fams.reduce((sum, f) => sum + (values[f.id] ?? 0), 0) / fams.length;
}

