// src/lib/politicalMetrics/derive/legacyInversion.ts
var qualityToScore = (q) => Math.max(0, Math.min(100, 50 + q * 50));
function politicalScoreFromLegacyValue(category, metricId, value, countryId, year) {
  if (!Number.isFinite(value)) return null;
  const definition = getMetricDefinition(category, metricId);
  if (!definition) return null;
  const quality = normalizedMetricQuality(value, definition, metricId, countryId ?? null, year);
  if (!Number.isFinite(quality)) return null;
  return qualityToScore(quality);
}
function legacyValueFromPoliticalScore(category, metricId, score, era) {
  if (!Number.isFinite(score)) return null;
  if (metricId === "medianIncome") return null;
  const definition = getMetricDefinition(category, metricId);
  if (!definition) return null;
  const { min, max } = metricQualityRange(definition, metricId, era);
  if (!(max > min)) return null;
  const quality = Math.max(-1, Math.min(1, (score - 50) / 50));
  const normalized = definition.isHigherBetter ? (quality + 1) / 2 : 1 - (quality + 1) / 2;
  return min + normalized * (max - min);
}

// src/lib/politicalMetrics/engineTerm.ts
var ENGINE_WEIGHT = 0.5;
var ENGINE_BOUND = 12;
var clamp3 = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
var ENGINE_PATHS_BY_FAMILY = (() => {
  const byFamily = {};
  for (const [legacyPath, familyId] of Object.entries(ADAPTER_TIER1)) {
    (byFamily[familyId] ??= []).push(legacyPath);
  }
  return byFamily;
})();
function engineTermFor(familyId, lawTarget, nodeOutputs, countryId, year) {
  const paths = ENGINE_PATHS_BY_FAMILY[familyId];
  if (!paths?.length) return 0;
  const scores = [];
  for (const path of paths) {
    const raw = nodeOutputs[path];
    if (raw == null || !Number.isFinite(raw)) continue;
    const [category, metricId] = path.split(".");
    const score = politicalScoreFromLegacyValue(category, metricId, raw, countryId, year);
    if (score != null) scores.push(score);
  }
  if (scores.length === 0) return 0;
  const engineScore = scores.reduce((a, b) => a + b, 0) / scores.length;
  return clamp3((engineScore - lawTarget) * ENGINE_WEIGHT, -ENGINE_BOUND, ENGINE_BOUND);
}

