var PROJECTED_CATEGORIES = /* @__PURE__ */ new Set([
  "education",
  "healthcare",
  "infrastructure",
  "publicSafety",
  "environment",
  "social",
  "governance",
  "mediaInformation"
]);
var PROJECTABLE_PATHS = Object.keys(ADAPTER_TIER1).filter(
  (path) => PROJECTED_CATEGORIES.has(path.split(".")[0])
);
function legacyPoliticalHalfFromBoard(values, era) {
  if (!values || Object.keys(values).length === 0) return null;
  const out = {};
  for (const path of PROJECTABLE_PATHS) {
    const [category, metricId] = path.split(".");
    const score = politicalValueForLegacyMetric(values, category, metricId);
    if (score == null) continue;
    const value = legacyValueFromPoliticalScore(category, metricId, score, era);
    if (value == null || !Number.isFinite(value)) continue;
    (out[category] ??= {})[metricId] = { value };
  }
  return Object.keys(out).length > 0 ? out : null;
}

