// src/lib/politicalLegislation/catalog.ts
var CORE_CATALOGS = {
  US: US_LAWS,
  UK: UK_LAWS,
  RU: RU_LAWS,
  DD: DD_LAWS
};
var CATALOGS = {
  US: [...CORE_CATALOGS.US, ...US_STATE_TAX_LAWS],
  UK: CORE_CATALOGS.UK,
  RU: CORE_CATALOGS.RU,
  DD: [...CORE_CATALOGS.DD, ...DD_LAND_LAWS]
};
var LAWS_BY_ID = new Map(
  Object.values(CATALOGS).flat().map((law) => [law.id, law])
);
function isLawActive(law, year) {
  if (!law.window) return true;
  if (year < law.window.from) return false;
  if (law.window.to != null && year > law.window.to) return false;
  return true;
}
function getCatalog(countryId, year) {
  const all = CATALOGS[countryId] ?? [];
  return year == null ? all : all.filter((law) => isLawActive(law, year));
}

// src/lib/politicalLegislation/dynamics.ts
var PRIMARY_POINTS_PER_LEVEL = 12.5;
var SECONDARY_POINTS_PER_LEVEL = 5;
var REGIONAL_SUPPLEMENT_FACTOR = 0.5;
var DRIFT_RATE_PER_TURN = 0.02;
var DRIFT_FLOOR = 0.01;
function lawPoints(kind, level, weight) {
  return kind === "primary" ? PRIMARY_POINTS_PER_LEVEL * level : SECONDARY_POINTS_PER_LEVEL * level * weight;
}
function lawTargets(countryId, levels) {
  const out = {};
  for (const family of POLITICAL_METRIC_FAMILIES) out[family.id] = 0;
  for (const law of getCatalog(countryId)) {
    if (law.kind === "tax") continue;
    const level = levels.get(law.id) ?? 0;
    if (level <= 0) continue;
    for (const target of law.targets) {
      out[target.metricId] += lawPoints(law.kind, level, target.weight);
    }
  }
  return out;
}
function structuralResidual(value, nationalPoints, regionalSupplementPoints) {
  return value - (nationalPoints + REGIONAL_SUPPLEMENT_FACTOR * regionalSupplementPoints);
}
function composeTarget(nationalPoints, regionalSupplementPoints, residual) {
  const target = nationalPoints + REGIONAL_SUPPLEMENT_FACTOR * regionalSupplementPoints + residual;
  return Math.max(0, Math.min(100, target));
}
function driftStep(value, target) {
  const gap = target - value;
  if (Math.abs(gap) <= DRIFT_FLOOR + 1e-9) return target;
  let step = gap * DRIFT_RATE_PER_TURN;
  if (Math.abs(step) < DRIFT_FLOOR) step = DRIFT_FLOOR * Math.sign(gap);
  return value + step;
}

